// HasChannelRefs applies the HasEdge predicate on the "channel_refs" edge.
func HasChannelRefs() predicate.UpstreamCredential {
	return predicate.UpstreamCredential(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ChannelRefsTable, ChannelRefsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasChannelRefsWith applies the HasEdge predicate on the "channel_refs" edge with a given conditions (other predicates).
func HasChannelRefsWith(preds ...predicate.ChannelCredentialRef) predicate.UpstreamCredential {
	return predicate.UpstreamCredential(func(s *sql.Selector) {
		step := newChannelRefsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

